/// Generate a deterministic seasonal series: y(t) = 10 + 0.5*t + 3*sin(2*pi*t/24)
fn generate_seasonal_series(length: usize, seasonality: usize) -> Vec<f64> {
    (0..length)
        .map(|t| {
            let trend = 10.0 + 0.5 * t as f64;
            let seasonal = 3.0 * ((2.0 * core::f64::consts::PI * t as f64) / seasonality as f64).sin();
            trend + seasonal
        })
        .collect()
}

/// Generate a constant series (degenerate case)
fn generate_constant_series(length: usize, value: f64) -> Vec<f64> {
    alloc::vec![value; length]
}

/// Generate a pure linear trend (no seasonality)
fn generate_linear_series(length: usize, slope: f64, intercept: f64) -> Vec<f64> {
    (0..length)
        .map(|t| intercept + slope * t as f64)
        .collect()
}

