#[test]
fn test_default_config_is_valid() {
    let config = HoltWintersConfig::default();
    assert!(config.alpha > 0.0 && config.alpha < 1.0, "alpha must be in (0,1)");
    assert!(config.beta > 0.0 && config.beta < 1.0, "beta must be in (0,1)");
    assert!(config.gamma > 0.0 && config.gamma < 1.0, "gamma must be in (0,1)");
    assert!(config.seasonality > 0, "seasonality must be positive");
}

#[test]
fn test_config_boundary_values() {
    // Alpha boundary
    let config = HoltWintersConfig { alpha: 0.001, ..HoltWintersConfig::default() };
    assert!(config.alpha > 0.0);
    let config = HoltWintersConfig { alpha: 0.999, ..HoltWintersConfig::default() };
    assert!(config.alpha < 1.0);

    // Beta boundary
    let config = HoltWintersConfig { beta: 0.001, ..HoltWintersConfig::default() };
    assert!(config.beta > 0.0);
    let config = HoltWintersConfig { beta: 0.999, ..HoltWintersConfig::default() };
    assert!(config.beta < 1.0);

    // Gamma boundary
    let config = HoltWintersConfig { gamma: 0.001, ..HoltWintersConfig::default() };
    assert!(config.gamma > 0.0);
    let config = HoltWintersConfig { gamma: 0.999, ..HoltWintersConfig::default() };
    assert!(config.gamma < 1.0);
}

#[test]
fn test_seasonality_minimum() {
    let config = HoltWintersConfig { seasonality: 1, ..HoltWintersConfig::default() };
    assert!(config.seasonality >= 1);
}

#[test]
fn test_seasonal_mode_equality() {
    assert_eq!(SeasonalMode::Additive, SeasonalMode::Additive);
    assert_eq!(SeasonalMode::Multiplicative, SeasonalMode::Multiplicative);
    assert_ne!(SeasonalMode::Additive, SeasonalMode::Multiplicative);
}

