#[test]
fn test_fit_constant_series() {
    let data = generate_constant_series(100, 42.0);
    let config = HoltWintersConfig::default();
    let model = HoltWintersModel::new(config);
    
    let fitted = model.fit(&data);
    assert!(fitted.is_ok(), "Fitting constant series should succeed");
    
    let fitted_model = fitted.unwrap();
    let forecast = fitted_model.forecast(1);
    assert!((forecast[0] - 42.0).abs() < 1e-6, "Forecast should approximate constant value");
}

#[test]
fn test_fit_linear_series() {
    let data = generate_linear_series(200, 2.0, 5.0);
    let config = HoltWintersConfig { seasonality: 1, ..HoltWintersConfig::default() };
    let model = HoltWintersModel::new(config);
    
    let fitted = model.fit(&data);
    assert!(fitted.is_ok(), "Fitting linear series should succeed");
    
    let fitted_model = fitted.unwrap();
    let forecast = fitted_model.forecast(5);
    // Expected: y(200) = 5 + 2*199 = 403, y(201) = 405, ...
    assert!((forecast[0] - 405.0).abs() < 1.0, "Forecast should track linear trend");
}

#[test]
fn test_fit_seasonal_series_additive() {
    let data = generate_seasonal_series(500, 24);
    let config = HoltWintersConfig {
        seasonality: 24,
        seasonal_mode: SeasonalMode::Additive,
        ..HoltWintersConfig::default()
    };
    let model = HoltWintersModel::new(config);
    
    let fitted = model.fit(&data);
    assert!(fitted.is_ok(), "Fitting seasonal series should succeed");
    
    let fitted_model = fitted.unwrap();
    let forecast = fitted_model.forecast(24);
    assert_eq!(forecast.len(), 24, "Forecast horizon should match request");
    
    // Verify seasonal pattern is preserved
    let seasonal_amplitude = forecast.iter().fold(0.0_f64, |acc, &x| acc.max(x.abs()));
    assert!(seasonal_amplitude > 0.5, "Seasonal pattern should be detected");
}

