#[test]
fn test_additive_multiplicative_equivalence_on_constant_seasonality() {
    // For data with zero seasonal amplitude, both modes should converge
    let data = generate_linear_series(200, 1.0, 10.0);
    
    let config_add = HoltWintersConfig {
        seasonality: 12,
        seasonal_mode: SeasonalMode::Additive,
        ..HoltWintersConfig::default()
    };
    let config_mul = HoltWintersConfig {
        seasonality: 12,
        seasonal_mode: SeasonalMode::Multiplicative,
        ..HoltWintersConfig::default()
    };
    
    let model_add = HoltWintersModel::new(config_add);
    let model_mul = HoltWintersModel::new(config_mul);
    
    let fitted_add = model_add.fit(&data).unwrap();
    let fitted_mul = model_mul.fit(&data).unwrap();
    
    let forecast_add = fitted_add.forecast(12);
    let forecast_mul = fitted_mul.forecast(12);
    
    // Both should produce similar forecasts for non-seasonal data
    for (a, m) in forecast_add.iter().zip(forecast_mul.iter()) {
        assert!((a - m).abs() < 10.0, "Modes should converge for non-seasonal data");
    }
}

