#[test]
fn test_forecast_monotonicity_for_positive_trend() {
    // For increasing data, forecasts should be non-decreasing
    let data = generate_linear_series(200, 1.0, 0.0);
    let config = HoltWintersConfig { seasonality: 1, ..HoltWintersConfig::default() };
    let model = HoltWintersModel::new(config);
    let fitted_model = model.fit(&data).unwrap();
    
    let forecast = fitted_model.forecast(20);
    for window in forecast.windows(2) {
        assert!(window[1] >= window[0] - 0.1, "Forecasts should be non-decreasing for positive trend");
    }
}

#[test]
fn test_forecast_seasonal_periodicity() {
    // Forecasts should exhibit seasonal periodicity
    let data = generate_seasonal_series(500, 24);
    let config = HoltWintersConfig {
        seasonality: 24,
        seasonal_mode: SeasonalMode::Additive,
        ..HoltWintersConfig::default()
    };
    let model = HoltWintersModel::new(config);
    let fitted_model = model.fit(&data).unwrap();
    
    let forecast = fitted_model.forecast(48);
    // Compare points 24 apart
    for i in 0..24 {
        let diff = (forecast[i] - forecast[i + 24]).abs();
        assert!(diff < 5.0, "Seasonal periodicity should be preserved (diff={})", diff);
    }
}

