#[test]
fn test_end_to_end_workflow() {
    // Complete workflow: generate → fit → forecast → validate
    let data = generate_seasonal_series(1000, 24);
    
    // Split: use first 800 points for training, last 200 for validation
    let train = &data[..800];
    let validation = &data[800..];
    
    let config = HoltWintersConfig {
        alpha: 0.3,
        beta: 0.1,
        gamma: 0.2,
        seasonality: 24,
        seasonal_mode: SeasonalMode::Additive,
    };
    let model = HoltWintersModel::new(config);
    let fitted_model = model.fit(train).unwrap();
    
    // Forecast 200 points ahead
    let forecast = fitted_model.forecast(200);
    
    // Calculate Mean Absolute Error (MAE)
    let mae: f64 = forecast.iter()
        .zip(validation.iter())
        .map(|(f, v)| (f - v).abs())
        .sum::<f64>() / 200.0;
    
    // MAE should be reasonable for this synthetic data
    assert!(mae < 5.0, "MAE should be < 5.0, got {}", mae);
}

#[test]
fn test_parameter_sensitivity() {
    // Different alpha values should produce different forecasts
    let data = generate_seasonal_series(300, 24);
    
    let config_smooth = HoltWintersConfig {
        alpha: 0.1,
        ..HoltWintersConfig::default()
    };
    let config_reactive = HoltWintersConfig {
        alpha: 0.9,
        ..HoltWintersConfig::default()
    };
    
    let model_smooth = HoltWintersModel::new(config_smooth);
    let model_reactive = HoltWintersModel::new(config_reactive);
    
    let fitted_smooth = model_smooth.fit(&data).unwrap();
    let fitted_reactive = model_reactive.fit(&data).unwrap();
    
    let forecast_smooth = fitted_smooth.forecast(5);
    let forecast_reactive = fitted_reactive.forecast(5);
    
    // Forecasts should differ due to different smoothing
    let max_diff = forecast_smooth.iter()
        .zip(forecast_reactive.iter())
        .map(|(a, b)| (a - b).abs())
        .fold(0.0_f64, f64::max);
    
    assert!(max_diff > 0.01, "Different alpha values should produce different forecasts");
}

