/// Assert that all values in a slice are finite
fn assert_all_finite(values: &[f64]) {
    for &v in values {
        assert!(v.is_finite(), "Value must be finite, got {}", v);
    }
}

/// Assert that all values in a slice are within a tolerance of a target
fn assert_all_close(values: &[f64], target: f64, tolerance: f64) {
    for &v in values {
        assert!((v - target).abs() < tolerance, "Value {} not within {} of {}", v, tolerance, target);
    }
}

